// Biotechnology and Its Applications — generated by Claude (no source PDF).
// Covers applications in agriculture (Bt crops, RNAi-based pest resistance),
// medicine (gene therapy, molecular diagnosis, insulin/humulin production),
// transgenic animals, and biosafety/ethical/regulatory issues (GEAC, biopiracy).

export const BIOTECH_APPLICATIONS = [
  // ---- MCQ ----
  { id: 'bta-1', type: 'mcq', question: 'The bacterium from which the widely used Bt toxin gene is derived is:', options: ['Escherichia coli', 'Bacillus thuringiensis', 'Agrobacterium tumefaciens', 'Thermus aquaticus'], correctIndex: 1, explanation: 'Bacillus thuringiensis produces crystal (Bt) proteins toxic to specific insect larvae.', difficulty: 'easy' },
  { id: 'bta-2', type: 'mcq', question: 'The Bt toxin genes commonly used in Bt cotton to confer resistance to bollworms are named:', options: ['cryIAc and cryIIAb', 'ampR and tetR', 'ori and lacZ', 'rbcL and psbA'], correctIndex: 0, explanation: 'cryIAc and cryIIAb are Bt toxin genes engineered into cotton to resist cotton bollworms.', difficulty: 'medium' },
  { id: 'bta-3', type: 'mcq', question: 'The Bt toxin protein exists in bacteria as:', options: ['An immediately active toxin', 'An inactive protoxin that is activated inside the insect gut', 'A form that is toxic to all animals equally', 'A toxin that only affects plant cells'], correctIndex: 1, explanation: 'Bt toxin is produced as an inactive protoxin, activated only after ingestion by susceptible insects.', difficulty: 'medium' },
  { id: 'bta-4', type: 'mcq', question: 'The Bt protoxin is converted into its active, toxic form inside the insect due to:', options: ['The acidic pH of the insect gut', 'The alkaline pH of the insect gut', 'High temperature inside the insect body', 'UV exposure inside the insect gut'], correctIndex: 1, explanation: "The alkaline environment of the insect's gut solubilises the crystal and activates the protoxin.", difficulty: 'medium' },
  { id: 'bta-5', type: 'mcq', question: 'Once activated, the Bt toxin kills susceptible insect larvae by:', options: ['Blocking their respiration directly', 'Binding to the midgut epithelial cells and creating pores, causing cell swelling and lysis', 'Preventing them from moving', 'Destroying their exoskeleton'], correctIndex: 1, explanation: 'Activated Bt toxin binds midgut epithelium, forms pores, causing cell swelling/lysis and eventual death of the insect.', difficulty: 'medium' },
  { id: 'bta-6', type: 'mcq', question: 'Bt toxin is generally considered safe for humans mainly because:', options: ['Humans lack the specific gut receptors and pH conditions needed to activate/bind the toxin', 'Humans are immune to all bacterial toxins', 'The toxin is destroyed by sunlight before consumption', 'Humans do not eat any Bt crops'], correctIndex: 0, explanation: "The human gut's different pH and lack of specific midgut receptors mean Bt toxin cannot be activated or bind effectively, unlike in target insects.", difficulty: 'medium' },
  { id: 'bta-7', type: 'mcq', question: 'RNA interference (RNAi) has been used to protect tobacco plants from infestation by which parasite?', options: ['Bacillus thuringiensis', 'Meloidogyne incognitae (a nematode)', 'Agrobacterium tumefaciens', 'Puccinia graminis'], correctIndex: 1, explanation: 'RNAi technology was used to make tobacco plants resistant to the nematode Meloidogyne incognitae, which infests roots.', difficulty: 'medium' },
  { id: 'bta-8', type: 'mcq', question: 'The RNAi-based strategy for nematode resistance works by introducing genes that produce:', options: ['Only sense RNA specific to the nematode', 'Both sense and anti-sense RNA of a nematode-specific gene, forming double-stranded RNA', 'Only Bt toxin protein', 'Only antibodies against the nematode'], correctIndex: 1, explanation: 'Producing both sense and anti-sense RNA forms dsRNA, which silences the nematode-specific mRNA via RNAi.', difficulty: 'medium' },
  { id: 'bta-9', type: 'mcq', question: 'RNA interference (RNAi) is understood to occur naturally in eukaryotic cells mainly as a mechanism for:', options: ['Producing extra energy', 'Cellular defence against invasion by mobile genetic elements like transposons and viruses', 'Photosynthesis regulation', 'Cell wall synthesis'], correctIndex: 1, explanation: 'RNAi is a conserved eukaryotic defence mechanism against viruses and transposable (mobile) genetic elements.', difficulty: 'medium' },
  { id: 'bta-10', type: 'mcq', question: "'Golden Rice' is a genetically engineered crop biofortified with additional:", options: ['Iron content only', 'Beta-carotene (a precursor of Vitamin A)', 'Protein content only', 'Vitamin C'], correctIndex: 1, explanation: 'Golden Rice is engineered to accumulate beta-carotene, addressing Vitamin A deficiency in diets.', difficulty: 'easy' },
  { id: 'bta-11', type: 'mcq', question: 'The first approved instance of gene therapy in humans (1990) was used to treat a genetic deficiency of the enzyme:', options: ['Insulin', 'Adenosine deaminase (ADA)', 'Lactase', 'Alpha-1-antitrypsin'], correctIndex: 1, explanation: 'The first gene therapy trial in 1990 targeted ADA deficiency, a disorder affecting immune function.', difficulty: 'medium' },
  { id: 'bta-12', type: 'mcq', question: 'In the classic approach to gene therapy for ADA deficiency, normal genetic material (a functional cDNA) is introduced into:', options: ['The patient\'s red blood cells', 'The patient\'s lymphocytes (later attempted at the stem cell level for a permanent cure)', 'The patient\'s skin cells only', 'The patient\'s hair follicles'], correctIndex: 1, explanation: 'Functional ADA cDNA was introduced into lymphocytes; targeting bone marrow stem cells was later explored for a more permanent fix.', difficulty: 'medium' },
  { id: 'bta-13', type: 'mcq', question: 'ELISA, a technique used for molecular diagnosis of diseases such as HIV infection, is based on the principle of:', options: ['DNA-DNA hybridisation', 'Antigen-antibody interaction', 'Restriction enzyme digestion', 'Gel electrophoresis'], correctIndex: 1, explanation: 'ELISA (Enzyme-Linked Immunosorbent Assay) detects the presence of a specific antigen or antibody via antigen-antibody binding.', difficulty: 'easy' },
  { id: 'bta-14', type: 'mcq', question: 'PCR is especially useful for early diagnosis of diseases like AIDS because it can detect:', options: ['Antibodies only, even in trace amounts', 'Very low quantities of the causative pathogen\'s DNA/RNA before antibodies have formed', 'Only visible symptoms', 'Only bacterial infections, not viral ones'], correctIndex: 1, explanation: 'PCR can amplify and detect minute amounts of pathogen genetic material early on, before the immune response produces detectable antibodies.', difficulty: 'medium' },
  { id: 'bta-15', type: 'mcq', question: 'Molecular diagnosis using a specific DNA probe to identify mutations in genes responsible for cancers is an application of which technique?', options: ['ELISA only', 'Probe-based hybridisation techniques (e.g., using specific DNA/RNA probes)', 'Only gel electrophoresis', 'Only microscopy'], correctIndex: 1, explanation: 'Specific labelled probes can hybridise to mutated sequences, helping identify cancer-associated mutations.', difficulty: 'medium' },
  { id: 'bta-16', type: 'mcq', question: 'Animals that carry a foreign gene deliberately introduced and expressed in their genome are called:', options: ['Hybrid animals', 'Transgenic animals', 'Clone animals only', 'Chimeric animals only'], correctIndex: 1, explanation: 'Transgenic animals have had their genome deliberately altered by introducing foreign DNA.', difficulty: 'easy' },
  { id: 'bta-17', type: 'mcq', question: 'One well-known application of transgenic animals involves engineering cows to produce milk containing:', options: ['Extra fat only', 'A human protein such as alpha-lactalbumin or a therapeutic protein', 'No lactose at all', 'Extra water content'], correctIndex: 1, explanation: 'Transgenic cows (e.g., "Rosie") have been engineered to produce milk enriched with human proteins for nutritional/therapeutic use.', difficulty: 'medium' },
  { id: 'bta-18', type: 'mcq', question: 'Transgenic mice are commonly used in biomedical research primarily to:', options: ['Replace all animal testing entirely', 'Study the safety of vaccines (e.g., polio vaccine) and understand disease processes/gene function', 'Serve only as household pets', 'Increase milk production only'], correctIndex: 1, explanation: 'Transgenic mice serve as models for vaccine safety testing, studying gene function, and modelling human diseases.', difficulty: 'medium' },
  { id: 'bta-19', type: 'mcq', question: 'In India, the regulatory body responsible for approving research involving genetically modified organisms and assessing the safety of introducing GM products is the:', options: ['ICMR', 'GEAC (Genetic Engineering Approval Committee)', 'UGC', 'AICTE'], correctIndex: 1, explanation: 'GEAC makes decisions regarding the validity and safety of GM research and products in India.', difficulty: 'medium' },
  { id: 'bta-20', type: 'mcq', question: "The unauthorised use or exploitation of a country's biological resources and traditional knowledge, typically by other nations or companies without compensation, is called:", options: ['Bioremediation', 'Biopiracy', 'Biofortification', 'Bioinformatics'], correctIndex: 1, explanation: 'Biopiracy refers to exploiting biological resources/traditional knowledge without proper authorisation or benefit-sharing.', difficulty: 'medium' },
  { id: 'bta-21', type: 'mcq', question: 'The well-known case where a foreign company attempted to patent a variety of Indian rice, sparking biopiracy concerns, involved:', options: ['Golden rice', 'Basmati rice', 'Bt rice', 'Wild rice from the Amazon'], correctIndex: 1, explanation: 'The Basmati rice patent case is a widely cited example of alleged biopiracy involving India\'s traditional crop variety.', difficulty: 'medium' },
  { id: 'bta-22', type: 'mcq', question: 'Genetically modified crops engineered to resist attack by specific insect pests primarily benefit farmers by:', options: ['Increasing the need for chemical pesticides', 'Reducing dependence on chemical pesticides while protecting yield', 'Making crops taste different', 'Making crops grow only in winter'], correctIndex: 1, explanation: 'Built-in pest resistance (like Bt cotton) can reduce the need for external chemical pesticide application.', difficulty: 'easy' },
  { id: 'bta-23', type: 'mcq', question: 'Which of these is an example of using biotechnology to address a micronutrient deficiency through crop biofortification?', options: ['Bt cotton', 'Golden Rice (enhanced beta-carotene)', 'FlavrSavr tomato', 'Transgenic mice'], correctIndex: 1, explanation: 'Golden Rice specifically targets Vitamin A deficiency through biofortification with beta-carotene.', difficulty: 'medium' },
  { id: 'bta-24', type: 'mcq', question: 'A key ethical/biosafety concern regarding genetically modified crops includes:', options: ['Their effect on biodiversity and potential unintended ecological consequences', 'Their inability to grow at all', 'Their complete lack of nutritional value', 'Their total resistance to all pathogens with no side effects'], correctIndex: 0, explanation: 'GM crop biosafety debates commonly focus on potential ecological impacts, gene flow to wild relatives, and biodiversity concerns.', difficulty: 'medium' },
  { id: 'bta-25', type: 'mcq', question: 'Which of the following best describes why gene therapy for ADA deficiency was later attempted at the level of bone marrow stem cells rather than just mature lymphocytes?', options: ['Stem cells are easier to extract', 'Stem cells can provide a permanent supply of corrected cells throughout the patient\'s life', 'Lymphocytes cannot be modified at all', 'Stem cells are cheaper to culture'], correctIndex: 1, explanation: 'Since stem cells continuously produce new lymphocytes, correcting them offers a longer-lasting/potentially permanent therapeutic effect compared to correcting mature lymphocytes alone.', difficulty: 'hard' },
  { id: 'bta-26', type: 'mcq', question: 'Which molecular diagnostic technique relies on labelled DNA/RNA probes hybridising with a complementary sequence to detect a specific gene or mutation?', options: ['ELISA', 'Nucleic acid hybridisation/probe-based techniques', 'Simple light microscopy', 'Gram staining'], correctIndex: 1, explanation: 'Nucleic acid hybridisation with labelled probes allows highly specific detection of target sequences, including disease-linked mutations.', difficulty: 'medium' },
  { id: 'bta-27', type: 'mcq', question: 'The main advantage of using recombinant DNA technology to produce human insulin (rather than extracting it from animal pancreases) is:', options: ['It produces insulin identical to human insulin, reducing immune reactions', 'It makes insulin taste better', 'It eliminates the need for insulin altogether', 'It makes insulin last forever without refrigeration'], correctIndex: 0, explanation: 'Recombinant human insulin is structurally identical to natural human insulin, reducing immunogenic side effects compared to animal-derived insulin.', difficulty: 'medium' },
  { id: 'bta-28', type: 'mcq', question: 'Which of these organisms/systems is genetically engineered to produce human insulin commercially?', options: ['Genetically modified Escherichia coli producing the A and B chains of insulin', 'Genetically modified cattle only', 'Wild-type yeast with no modification', 'Genetically modified mosquitoes'], correctIndex: 0, explanation: 'Recombinant E. coli strains are engineered to produce the A and B polypeptide chains of human insulin, later combined via disulfide bonds.', difficulty: 'medium' },
  { id: 'bta-29', type: 'mcq', question: 'Why is RNA interference (RNAi)-based pest resistance considered advantageous compared to Bt toxin-based resistance in some cases?', options: ['It works only on bacteria', 'It can specifically silence a pest\'s own essential genes without producing a foreign toxin protein', 'It requires no genetic engineering at all', 'It cannot be used in any plant species'], correctIndex: 1, explanation: 'RNAi silences a specific pest gene at the RNA level rather than relying on a toxin protein, offering a potentially more targeted approach.', difficulty: 'hard' },
  { id: 'bta-30', type: 'mcq', question: 'Which of the following would be an appropriate summary of how transgenic animals contribute to biomedical research?', options: ['They are used only for agricultural food production, with no research value', 'They allow researchers to study gene function, model human diseases, test biological product safety, and produce valuable proteins', 'They can only be used to test cosmetics', 'They eliminate the need for any further human clinical trials'], correctIndex: 1, explanation: 'Transgenic animals serve multiple biomedical roles — from studying gene/disease biology to producing therapeutic proteins and testing safety.', difficulty: 'medium' },

  // ---- Assertion-Reason ----
  { id: 'bta-ar-1', type: 'assertion-reason', question: 'Assertion (A): Bt cotton is resistant to bollworm attack.\nReason (R): Bt cotton plants express a bacterial toxin gene from Bacillus thuringiensis that is lethal to specific insect larvae.', options: ['Both A and R are true, and R is the correct explanation of A', 'Both A and R are true, but R is NOT the correct explanation of A', 'A is true, but R is false', 'A is false, but R is true'], correctIndex: 0, explanation: 'Expression of the Bt toxin gene directly confers resistance by killing susceptible insect larvae that feed on the plant.', difficulty: 'medium' },
  { id: 'bta-ar-2', type: 'assertion-reason', question: 'Assertion (A): Bt toxin harms humans as much as it harms target insect larvae.\nReason (R): Bt toxin protoxin is activated only in an alkaline pH environment, which is characteristic of the target insect gut and absent in the human digestive system in the same way.', options: ['Both A and R are true, and R is the correct explanation of A', 'Both A and R are true, but R is NOT the correct explanation of A', 'A is true, but R is false', 'A is false, but R is true'], correctIndex: 3, explanation: 'Bt toxin does NOT harm humans similarly (A is false), precisely because the specific activation conditions and receptors needed are not present in humans (R is true).', difficulty: 'medium' },
  { id: 'bta-ar-3', type: 'assertion-reason', question: 'Assertion (A): RNA interference was used to make tobacco plants resistant to a nematode.\nReason (R): Both sense and anti-sense RNA against a nematode-specific gene were expressed, forming dsRNA that silenced the target mRNA via RNAi.', options: ['Both A and R are true, and R is the correct explanation of A', 'Both A and R are true, but R is NOT the correct explanation of A', 'A is true, but R is false', 'A is false, but R is true'], correctIndex: 0, explanation: 'Formation of dsRNA that silences the nematode gene is exactly the mechanism behind this RNAi-based resistance strategy.', difficulty: 'medium' },
  { id: 'bta-ar-4', type: 'assertion-reason', question: 'Assertion (A): RNA interference does not naturally occur in eukaryotic cells; it was invented entirely by biotechnologists.\nReason (R): RNAi is a natural mechanism of cellular defence used by many eukaryotes against viruses and mobile genetic elements.', options: ['Both A and R are true, and R is the correct explanation of A', 'Both A and R are true, but R is NOT the correct explanation of A', 'A is true, but R is false', 'A is false, but R is true'], correctIndex: 3, explanation: 'RNAi actually occurs naturally in eukaryotes (A is false) — scientists harnessed this pre-existing mechanism, as R correctly states.', difficulty: 'medium' },
  { id: 'bta-ar-5', type: 'assertion-reason', question: 'Assertion (A): Golden Rice was developed to address protein-energy malnutrition.\nReason (R): Golden Rice is genetically engineered to accumulate beta-carotene, a precursor of Vitamin A.', options: ['Both A and R are true, and R is the correct explanation of A', 'Both A and R are true, but R is NOT the correct explanation of A', 'A is true, but R is false', 'A is false, but R is true'], correctIndex: 3, explanation: 'Golden Rice actually targets Vitamin A deficiency, not protein-energy malnutrition (A is false); R correctly describes its actual purpose.', difficulty: 'medium' },
  { id: 'bta-ar-6', type: 'assertion-reason', question: 'Assertion (A): Gene therapy for ADA deficiency initially involved introducing normal ADA cDNA into lymphocytes.\nReason (R): Lymphocytes are not a permanent solution since they have a limited lifespan, motivating later approaches targeting bone marrow stem cells.', options: ['Both A and R are true, and R is the correct explanation of A', 'Both A and R are true, but R is NOT the correct explanation of A', 'A is true, but R is false', 'A is false, but R is true'], correctIndex: 0, explanation: 'Since lymphocytes eventually die off, targeting stem cells (which continuously regenerate lymphocytes) was pursued for a more lasting fix — R directly explains this progression.', difficulty: 'medium' },
  { id: 'bta-ar-7', type: 'assertion-reason', question: 'Assertion (A): ELISA can be used to detect HIV infection.\nReason (R): ELISA is based on the specific interaction between an antigen and its corresponding antibody.', options: ['Both A and R are true, and R is the correct explanation of A', 'Both A and R are true, but R is NOT the correct explanation of A', 'A is true, but R is false', 'A is false, but R is true'], correctIndex: 0, explanation: 'Detecting HIV-specific antigens or antibodies via their specific binding is exactly how ELISA-based HIV tests work.', difficulty: 'easy' },
  { id: 'bta-ar-8', type: 'assertion-reason', question: 'Assertion (A): PCR is not useful for early diagnosis of diseases like AIDS.\nReason (R): PCR can detect pathogen genetic material even in very small quantities, before antibodies have been produced by the immune system.', options: ['Both A and R are true, and R is the correct explanation of A', 'Both A and R are true, but R is NOT the correct explanation of A', 'A is true, but R is false', 'A is false, but R is true'], correctIndex: 3, explanation: 'PCR is actually very useful for early diagnosis (A is false), precisely because of its sensitivity in detecting minute amounts of pathogen genetic material early on (R is true).', difficulty: 'medium' },
  { id: 'bta-ar-9', type: 'assertion-reason', question: "Assertion (A): Transgenic mice have been used to test the safety of the polio vaccine before human use.\nReason (R): Transgenic animals can be engineered to carry human-relevant genes/receptors, making them useful models for such safety testing.", options: ['Both A and R are true, and R is the correct explanation of A', 'Both A and R are true, but R is NOT the correct explanation of A', 'A is true, but R is false', 'A is false, but R is true'], correctIndex: 0, explanation: "Engineering mice with human-relevant susceptibility factors is exactly what makes them useful models for vaccine safety testing.", difficulty: 'medium' },
  { id: 'bta-ar-10', type: 'assertion-reason', question: 'Assertion (A): Transgenic cows have been developed to produce milk with additional human proteins.\nReason (R): This is done purely for increasing the fat content of milk for commercial dairy sale.', options: ['Both A and R are true, and R is the correct explanation of A', 'Both A and R are true, but R is NOT the correct explanation of A', 'A is true, but R is false', 'A is false, but R is true'], correctIndex: 2, explanation: 'A is true, but R is false — such milk-protein engineering is typically for nutritional/therapeutic purposes (e.g., producing a needed human protein), not simply to raise fat content.', difficulty: 'medium' },
  { id: 'bta-ar-11', type: 'assertion-reason', question: 'Assertion (A): GEAC is responsible for approving GM-related research and products in India.\nReason (R): Assessing the safety and validity of genetically modified organisms before their release requires a dedicated regulatory body.', options: ['Both A and R are true, and R is the correct explanation of A', 'Both A and R are true, but R is NOT the correct explanation of A', 'A is true, but R is false', 'A is false, but R is true'], correctIndex: 0, explanation: "The need for dedicated safety/validity assessment is exactly why a body like GEAC exists and performs this role.", difficulty: 'medium' },
  { id: 'bta-ar-12', type: 'assertion-reason', question: 'Assertion (A): Biopiracy refers to the legal and fully compensated use of a country\'s biological resources by foreign entities.\nReason (R): Biopiracy involves exploitation of biodiversity and traditional knowledge without proper authorisation or benefit-sharing.', options: ['Both A and R are true, and R is the correct explanation of A', 'Both A and R are true, but R is NOT the correct explanation of A', 'A is true, but R is false', 'A is false, but R is true'], correctIndex: 3, explanation: "Biopiracy is actually UNAUTHORISED/uncompensated use (A is false, since it describes the opposite); R correctly defines the real concept.", difficulty: 'medium' },
  { id: 'bta-ar-13', type: 'assertion-reason', question: 'Assertion (A): The Basmati rice case is frequently cited as an example of biopiracy.\nReason (R): A foreign company attempted to patent aspects of a rice variety long cultivated and known within India.', options: ['Both A and R are true, and R is the correct explanation of A', 'Both A and R are true, but R is NOT the correct explanation of A', 'A is true, but R is false', 'A is false, but R is true'], correctIndex: 0, explanation: "A patent claim over a traditionally known Indian crop variety is exactly why this case became a landmark biopiracy dispute.", difficulty: 'medium' },
  { id: 'bta-ar-14', type: 'assertion-reason', question: 'Assertion (A): Bt toxin genes were originally isolated from a virus.\nReason (R): Bt toxin genes were isolated from the soil bacterium Bacillus thuringiensis.', options: ['Both A and R are true, and R is the correct explanation of A', 'Both A and R are true, but R is NOT the correct explanation of A', 'A is true, but R is false', 'A is false, but R is true'], correctIndex: 3, explanation: 'Bt genes come from a bacterium, not a virus (A is false); R correctly identifies the actual bacterial source.', difficulty: 'easy' },
  { id: 'bta-ar-15', type: 'assertion-reason', question: 'Assertion (A): Recombinant human insulin production has largely replaced extraction of insulin from animal pancreases.\nReason (R): Recombinant insulin is chemically/structurally identical to natural human insulin, reducing the risk of immune reactions compared to animal-derived insulin.', options: ['Both A and R are true, and R is the correct explanation of A', 'Both A and R are true, but R is NOT the correct explanation of A', 'A is true, but R is false', 'A is false, but R is true'], correctIndex: 0, explanation: 'Being structurally identical and less immunogenic is exactly why recombinant insulin has largely replaced animal-extracted insulin.', difficulty: 'medium' },
  { id: 'bta-ar-16', type: 'assertion-reason', question: 'Assertion (A): Biosafety and ethical concerns are irrelevant when it comes to releasing genetically modified organisms into the environment.\nReason (R): GM organisms could potentially have unintended ecological effects, such as gene flow to wild relatives or effects on non-target species.', options: ['Both A and R are true, and R is the correct explanation of A', 'Both A and R are true, but R is NOT the correct explanation of A', 'A is true, but R is false', 'A is false, but R is true'], correctIndex: 3, explanation: 'Biosafety concerns are actually highly relevant (A is false); R correctly explains why such concerns exist for GM organism release.', difficulty: 'medium' },
  { id: 'bta-ar-17', type: 'assertion-reason', question: 'Assertion (A): Molecular diagnostic techniques like PCR and ELISA have made disease detection faster and more sensitive than many traditional methods.\nReason (R): These techniques can detect very small amounts of pathogen genetic material or specific antigens/antibodies.', options: ['Both A and R are true, and R is the correct explanation of A', 'Both A and R are true, but R is NOT the correct explanation of A', 'A is true, but R is false', 'A is false, but R is true'], correctIndex: 0, explanation: "High sensitivity to trace amounts of target material is exactly why these techniques enable faster, earlier detection.", difficulty: 'medium' },
  { id: 'bta-ar-18', type: 'assertion-reason', question: 'Assertion (A): All genetically modified crops are automatically approved for commercial cultivation without any regulatory review.\nReason (R): Bodies like GEAC exist specifically to evaluate and approve (or reject) GM crops before commercial release.', options: ['Both A and R are true, and R is the correct explanation of A', 'Both A and R are true, but R is NOT the correct explanation of A', 'A is true, but R is false', 'A is false, but R is true'], correctIndex: 3, explanation: 'GM crops are NOT automatically approved (A is false) — they must go through review by bodies like GEAC, as R correctly states.', difficulty: 'medium' },
  { id: 'bta-ar-19', type: 'assertion-reason', question: 'Assertion (A): Transgenic animals can be used to study the function of specific genes by observing effects of adding or removing them.\nReason (R): Introducing or knocking out a gene in an animal model can reveal its normal physiological role.', options: ['Both A and R are true, and R is the correct explanation of A', 'Both A and R are true, but R is NOT the correct explanation of A', 'A is true, but R is false', 'A is false, but R is true'], correctIndex: 0, explanation: 'Observing the phenotypic consequences of adding/removing a gene is exactly how such transgenic/knockout models reveal gene function.', difficulty: 'medium' },
  { id: 'bta-ar-20', type: 'assertion-reason', question: "Assertion (A): The RNAi-based nematode resistance strategy relies on producing a foreign toxin protein inside the plant.\nReason (R): RNAi works by silencing specific mRNA through double-stranded RNA, not by producing a toxin protein.", options: ['Both A and R are true, and R is the correct explanation of A', 'Both A and R are true, but R is NOT the correct explanation of A', 'A is true, but R is false', 'A is false, but R is true'], correctIndex: 3, explanation: 'RNAi resistance does NOT rely on a toxin protein (A is false) — it works at the RNA-silencing level, as R correctly explains.', difficulty: 'medium' },

  // ---- Statement-based ----
  { id: 'bta-st-1', type: 'statement', question: 'Statement I: Bt cotton expresses a toxin gene derived from Bacillus thuringiensis.\nStatement II: The Bt toxin is toxic to humans in the same way it is toxic to insect larvae.', options: ['Both correct', 'Both incorrect', 'I correct, II incorrect', 'II correct, I incorrect'], correctIndex: 2, explanation: 'Statement I is correct; Statement II is incorrect — Bt toxin requires specific conditions/receptors present in target insects but not in humans.', difficulty: 'medium' },
  { id: 'bta-st-2', type: 'statement', question: 'Statement I: RNAi-based nematode resistance in tobacco involves producing double-stranded RNA against a nematode-specific gene.\nStatement II: This dsRNA silences the nematode\'s own target mRNA, preventing infestation.', options: ['Both correct', 'Both incorrect', 'I correct, II incorrect', 'II correct, I incorrect'], correctIndex: 0, explanation: 'Both statements accurately describe the RNAi-based nematode resistance strategy.', difficulty: 'medium' },
  { id: 'bta-st-3', type: 'statement', question: 'Statement I: Golden Rice was developed to address iron-deficiency anaemia.\nStatement II: Golden Rice accumulates beta-carotene, a precursor of Vitamin A.', options: ['Both correct', 'Both incorrect', 'I correct, II incorrect', 'II correct, I incorrect'], correctIndex: 3, explanation: 'Statement I is incorrect — Golden Rice targets Vitamin A deficiency, not iron deficiency; Statement II correctly describes its actual biofortification target.', difficulty: 'medium' },
  { id: 'bta-st-4', type: 'statement', question: 'Statement I: The first approved human gene therapy trial targeted ADA deficiency.\nStatement II: This trial involved introducing a functional ADA gene into the patient\'s lymphocytes.', options: ['Both correct', 'Both incorrect', 'I correct, II incorrect', 'II correct, I incorrect'], correctIndex: 0, explanation: 'Both statements correctly describe the landmark 1990 ADA-deficiency gene therapy trial.', difficulty: 'medium' },
  { id: 'bta-st-5', type: 'statement', question: 'Statement I: ELISA relies on nucleic acid hybridisation to detect disease.\nStatement II: ELISA relies on antigen-antibody interactions to detect disease.', options: ['Both correct', 'Both incorrect', 'I correct, II incorrect', 'II correct, I incorrect'], correctIndex: 3, explanation: 'Statement I is incorrect — that describes probe-based hybridisation techniques, not ELISA; Statement II correctly describes the actual ELISA principle.', difficulty: 'medium' },
  { id: 'bta-st-6', type: 'statement', question: 'Statement I: PCR can detect pathogen DNA/RNA even before antibodies are produced.\nStatement II: This makes PCR particularly valuable for early diagnosis of diseases.', options: ['Both correct', 'Both incorrect', 'I correct, II incorrect', 'II correct, I incorrect'], correctIndex: 0, explanation: 'Both statements correctly capture why PCR is valuable for early disease detection.', difficulty: 'medium' },
  { id: 'bta-st-7', type: 'statement', question: 'Statement I: Transgenic animals always occur naturally without any human intervention.\nStatement II: Transgenic animals are deliberately engineered to carry and express foreign genes.', options: ['Both correct', 'Both incorrect', 'I correct, II incorrect', 'II correct, I incorrect'], correctIndex: 3, explanation: 'Statement I is incorrect — transgenic animals require deliberate genetic engineering; Statement II correctly describes how they are made.', difficulty: 'medium' },
  { id: 'bta-st-8', type: 'statement', question: 'Statement I: Transgenic mice have been used to test vaccine safety before human trials.\nStatement II: Transgenic cows have been engineered to produce milk with therapeutic human proteins.', options: ['Both correct', 'Both incorrect', 'I correct, II incorrect', 'II correct, I incorrect'], correctIndex: 0, explanation: 'Both statements correctly describe real applications of transgenic animals.', difficulty: 'medium' },
  { id: 'bta-st-9', type: 'statement', question: 'Statement I: GEAC is a regulatory body responsible for evaluating GM organism safety in India.\nStatement II: GEAC has no role in approving field trials of GM crops.', options: ['Both correct', 'Both incorrect', 'I correct, II incorrect', 'II correct, I incorrect'], correctIndex: 2, explanation: 'Statement I is correct; Statement II is incorrect — GEAC does play a role in approving field trials and release of GM crops.', difficulty: 'medium' },
  { id: 'bta-st-10', type: 'statement', question: 'Statement I: Biopiracy involves the unauthorised commercial use of a country\'s biological resources or traditional knowledge.\nStatement II: The Basmati rice patent dispute is often cited as an example of alleged biopiracy.', options: ['Both correct', 'Both incorrect', 'I correct, II incorrect', 'II correct, I incorrect'], correctIndex: 0, explanation: 'Both statements are correct descriptions of biopiracy and a well-known real-world example.', difficulty: 'medium' },
  { id: 'bta-st-11', type: 'statement', question: 'Statement I: Bt toxin protein is directly toxic in bacteria without requiring activation.\nStatement II: Bt toxin exists as an inactive protoxin that is only activated inside a susceptible insect\'s alkaline gut.', options: ['Both correct', 'Both incorrect', 'I correct, II incorrect', 'II correct, I incorrect'], correctIndex: 3, explanation: 'Statement I is incorrect — Bt toxin is produced as an inactive protoxin, not an immediately active toxin; Statement II correctly describes the activation process.', difficulty: 'medium' },
  { id: 'bta-st-12', type: 'statement', question: 'Statement I: RNA interference occurs naturally in many eukaryotic organisms as a defence mechanism.\nStatement II: Biotechnologists have harnessed this natural RNAi mechanism for applications like pest-resistant crops.', options: ['Both correct', 'Both incorrect', 'I correct, II incorrect', 'II correct, I incorrect'], correctIndex: 0, explanation: 'Both statements correctly describe RNAi as a natural mechanism that has been applied biotechnologically.', difficulty: 'medium' },
  { id: 'bta-st-13', type: 'statement', question: 'Statement I: Recombinant human insulin is produced using genetically modified bacteria.\nStatement II: Recombinant insulin is structurally different from natural human insulin, causing frequent immune reactions.', options: ['Both correct', 'Both incorrect', 'I correct, II incorrect', 'II correct, I incorrect'], correctIndex: 2, explanation: 'Statement I is correct; Statement II is incorrect — recombinant insulin is structurally IDENTICAL to natural human insulin, which is exactly why it causes fewer immune reactions.', difficulty: 'medium' },
  { id: 'bta-st-14', type: 'statement', question: 'Statement I: GM crop biosafety concerns include potential effects on non-target organisms and biodiversity.\nStatement II: These concerns are why regulatory bodies review GM crops before commercial release.', options: ['Both correct', 'Both incorrect', 'I correct, II incorrect', 'II correct, I incorrect'], correctIndex: 0, explanation: 'Both statements correctly connect biosafety concerns to the need for regulatory review.', difficulty: 'medium' },
  { id: 'bta-st-15', type: 'statement', question: 'Statement I: Molecular diagnostic techniques like ELISA and PCR have completely replaced traditional symptom-based diagnosis.\nStatement II: These techniques offer much greater sensitivity and speed compared to waiting for visible symptoms.', options: ['Both correct', 'Both incorrect', 'I correct, II incorrect', 'II correct, I incorrect'], correctIndex: 3, explanation: 'Statement I overstates the case — traditional diagnosis is still used alongside molecular techniques, not fully replaced; Statement II correctly highlights their advantage in sensitivity/speed.', difficulty: 'medium' },
  { id: 'bta-st-16', type: 'statement', question: 'Statement I: cryIAc and cryIIAb are Bt toxin genes used in cotton.\nStatement II: These genes are examples of selectable marker genes used to screen for transformed bacteria.', options: ['Both correct', 'Both incorrect', 'I correct, II incorrect', 'II correct, I incorrect'], correctIndex: 2, explanation: 'Statement I is correct; Statement II is incorrect — cry genes encode insecticidal toxins, not selectable markers.', difficulty: 'medium' },
  { id: 'bta-st-17', type: 'statement', question: 'Statement I: Gene therapy aims to correct a genetic defect diagnosed in a child or embryo by introducing a functional gene.\nStatement II: Gene therapy has been fully perfected with no remaining technical or ethical challenges.', options: ['Both correct', 'Both incorrect', 'I correct, II incorrect', 'II correct, I incorrect'], correctIndex: 2, explanation: 'Statement I correctly describes the general aim of gene therapy; Statement II is incorrect — gene therapy still faces significant technical and ethical challenges.', difficulty: 'medium' },
  { id: 'bta-st-18', type: 'statement', question: 'Statement I: Transgenic sheep and goats have been used to produce pharmaceutical proteins in their milk.\nStatement II: This approach is sometimes referred to as "molecular pharming" or biopharming.', options: ['Both correct', 'Both incorrect', 'I correct, II incorrect', 'II correct, I incorrect'], correctIndex: 0, explanation: 'Both statements correctly describe the use of transgenic livestock for producing pharmaceutical proteins.', difficulty: 'medium' },
  { id: 'bta-st-19', type: 'statement', question: 'Statement I: GEAC approval is required before large-scale commercial release of a new GM crop variety in India.\nStatement II: Once GEAC approves a crop for research trials, it is automatically approved for unrestricted commercial sale.', options: ['Both correct', 'Both incorrect', 'I correct, II incorrect', 'II correct, I incorrect'], correctIndex: 2, explanation: 'Statement I is correct; Statement II is incorrect — research trial approval and commercial release approval are distinct, sequential regulatory steps.', difficulty: 'medium' },
  { id: 'bta-st-20', type: 'statement', question: 'Statement I: Bt cotton has reduced the need for certain chemical pesticide applications in some regions.\nStatement II: This is because the cotton plant itself produces a toxin lethal to specific target pests.', options: ['Both correct', 'Both incorrect', 'I correct, II incorrect', 'II correct, I incorrect'], correctIndex: 0, explanation: 'Both statements correctly connect built-in pest resistance to reduced reliance on external pesticide spraying.', difficulty: 'medium' },

  // ---- "How many of the following are correct" ----
  { id: 'bta-hm-1', type: 'statement', question: 'How many of the following are genuine applications of biotechnology discussed in this chapter?\nBt cotton for pest resistance, RNAi-based nematode resistance in tobacco, Gene therapy for ADA deficiency, Golden Rice for Vitamin A biofortification', options: ['One', 'Two', 'Three', 'All four'], correctIndex: 3, explanation: 'All four are real, well-documented biotechnology applications covered in this area of study.', difficulty: 'easy' },
  { id: 'bta-hm-2', type: 'statement', question: 'How many of the following correctly describe the mechanism of Bt toxin action?\nIt exists as an inactive protoxin in the bacterium, It is activated by the alkaline pH of the target insect gut, It creates pores in midgut epithelial cells causing cell lysis, It works identically regardless of gut pH in any organism', options: ['One', 'Two', 'Three', 'Four'], correctIndex: 2, explanation: 'The first three statements are correct; the fourth is false — Bt toxin action specifically depends on the alkaline gut conditions of target insects.', difficulty: 'medium' },
  { id: 'bta-hm-3', type: 'statement', question: 'How many of the following are correctly associated with molecular diagnosis of diseases?\nELISA (antigen-antibody interaction), PCR (amplifying pathogen genetic material), Probe hybridisation for detecting mutations, Gel electrophoresis alone for identifying a specific pathogen species', options: ['One', 'Two', 'Three', 'Four'], correctIndex: 2, explanation: 'ELISA, PCR, and probe hybridisation are all genuine molecular diagnostic tools; gel electrophoresis alone (without further analysis) cannot specifically identify a pathogen species.', difficulty: 'medium' },
  { id: 'bta-hm-4', type: 'statement', question: 'How many of the following are true regarding transgenic animals?\nThey carry deliberately introduced foreign genes, They can be used to study gene function, They can produce therapeutic proteins in milk, They occur spontaneously in nature without any genetic engineering', options: ['One', 'Two', 'Three', 'Four'], correctIndex: 2, explanation: 'The first three statements correctly describe transgenic animals; the fourth is false, since transgenic status requires deliberate genetic engineering.', difficulty: 'medium' },
  { id: 'bta-hm-5', type: 'statement', question: 'How many of the following are regulatory/ethical concepts relevant to biotechnology applications?\nGEAC approval process, Biopiracy, Biosafety assessment of GM crops, Photosynthesis efficiency of a crop', options: ['One', 'Two', 'Three', 'Four'], correctIndex: 2, explanation: 'GEAC, biopiracy, and biosafety are all regulatory/ethical concepts central to biotechnology applications; photosynthetic efficiency is an agronomic trait, not a regulatory/ethical concept.', difficulty: 'medium' },
  { id: 'bta-hm-6', type: 'statement', question: 'How many of the following are true regarding RNAi-based pest resistance?\nIt involves producing dsRNA against a pest-specific gene, It silences the pest\'s own target mRNA, It was used to protect tobacco from nematode infestation, It relies on producing a bacterial toxin protein', options: ['One', 'Two', 'Three', 'Four'], correctIndex: 2, explanation: 'The first three statements correctly describe RNAi-based resistance; the fourth is false, as RNAi does not rely on a toxin protein at all.', difficulty: 'medium' },
  { id: 'bta-hm-7', type: 'statement', question: 'How many of the following are true regarding gene therapy for ADA deficiency?\nIt was among the first approved human gene therapy trials, It initially targeted the patient\'s lymphocytes, It was later attempted at the bone marrow stem cell level for a more permanent solution, It has completely eliminated ADA deficiency worldwide', options: ['One', 'Two', 'Three', 'Four'], correctIndex: 2, explanation: 'The first three statements are correct historical/technical facts; the fourth overstates the case — gene therapy has not eliminated the condition worldwide.', difficulty: 'medium' },
  { id: 'bta-hm-8', type: 'statement', question: 'How many of the following are examples or concepts related to biopiracy concerns?\nBasmati rice patent dispute, Unauthorised use of traditional medicinal plant knowledge, Patenting a naturally occurring gene sequence without benefit-sharing, Golden Rice biofortification for Vitamin A', options: ['One', 'Two', 'Three', 'Four'], correctIndex: 2, explanation: 'The first three are genuine biopiracy-related examples/concerns; Golden Rice biofortification is unrelated to biopiracy — it is a nutritional application.', difficulty: 'medium' },
  { id: 'bta-hm-9', type: 'statement', question: 'How many of the following are true regarding recombinant human insulin production?\nIt is produced using genetically modified bacteria like E. coli, It is structurally identical to natural human insulin, It reduces the risk of immune reactions compared to older animal-derived insulin, It requires extraction directly from human pancreases', options: ['One', 'Two', 'Three', 'Four'], correctIndex: 2, explanation: 'The first three statements are correct; the fourth is false — recombinant insulin production does NOT require extraction from human pancreases at all.', difficulty: 'medium' },
  { id: 'bta-hm-10', type: 'statement', question: 'How many of the following would typically require GEAC approval or review in India?\nField trials of a new GM crop, Commercial release of a GM food product, Basic laboratory research using standard non-GM crossbreeding, Environmental release of a genetically modified organism', options: ['One', 'Two', 'Three', 'Four'], correctIndex: 2, explanation: 'Field trials, commercial release, and environmental release of GMOs typically require GEAC review; standard non-GM crossbreeding does not fall under GEAC\'s GM-specific regulatory scope.', difficulty: 'hard' },
];
